"use strict";
eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   storiesList: () => (/* binding */ storiesList)\n/* harmony export */ });\nconst storiesList = [\n    {\n        slug: \"nehal-autism-journey\",\n        title: \"Sangarsh… Sah Harsh: Nehal’s Journey on the Autism Spectrum\",\n        subtitle: \"Written by her mother Seema, a story of art, resilience, and employment.\",\n        category: \"Literature & Arts\",\n        date: \"2022\",\n        author: \"Seema (Nehal’s Mother)\",\n        image: \"/images/stories/story-01.jpg\",\n        excerpt: \"Nehal is an artist and working woman on the autism spectrum. Her mother Seema shares the triumphs and struggles of nurturing an independent neurodivergent individual.\",\n        fullStory: [\n            'Published by Sangati Foundation, \"Sangarsh… Sah Harsh\" (Struggle with Joy) documents the journey of Nehal, an artist and working woman who navigates life on the autism spectrum.',\n            \"Written with immense warmth and honesty by her mother Seema, the book provides a beacon of guidance for families across India raising neurodivergent children.\",\n            \"Through her vibrant paintings and career accomplishments, Nehal proves that with early support, clear accommodations, and unconditional acceptance, individuals on the spectrum can thrive in creative and professional roles.\",\n            \"Sangati continues to distribute copies of this book to schools, caregiver groups, and community libraries to dismantle stigmas around neurodiversity.\"\n        ],\n        quote: \"Inclusion is not asking a person to adapt to our world; it is expanding our world to hold everyone.\"\n    },\n    {\n        slug: \"nizamuddin-station-accessibility\",\n        title: \"Making Hazrat Nizamuddin Railway Hub Fully Accessible\",\n        subtitle: \"Collaborative audit and solution design for locomotor and visual disability.\",\n        category: \"Accessibility\",\n        date: \"2024\",\n        author: \"Sangati Accessibility Team\",\n        image: \"/images/stories/story-02.jpg\",\n        excerpt: \"In partnership with Yatra and Anuprayaas, Sangati redesigned navigation, ramps, and tactile paths at one of India’s busiest railway terminals.\",\n        fullStory: [\n            \"Railway stations in India are bustling gateways, but for millions of passengers with disabilities, they present daunting barriers — steep stairs, missing handrails, and unreadable platforms.\",\n            \"Sangati Foundation collaborated with Yatra and Anuprayaas to undertake a comprehensive accessibility audit and physical transformation of Hazrat Nizamuddin Railway Station.\",\n            \"The upgrades included tactile paving pathways leading directly from entrance gates to train platforms, step-free ramp access, braille maps, high-contrast directional signage, and sensitized railway staff.\",\n            \"This project serves as a model benchmark for Indian Railways to replicate across major junctions nationwide.\"\n        ],\n        quote: \"Public transport is a basic constitutional right. A train platform without a ramp is a door locked against millions.\"\n    },\n    {\n        slug: \"sangati-yatra-2024-expedition\",\n        title: \"6,000 Kilometers Driven by Five Divyang Trailblazers\",\n        subtitle: \"From New Delhi to Dhanushkodi and back: proving distance is no barrier.\",\n        category: \"Mobility & Campaign\",\n        date: \"Jan 2025\",\n        author: \"Sudhir Dhir\",\n        image: \"/images/stories/story-03.jpg\",\n        excerpt: \"Founder Sudhir Dhir and four fellow drivers with disability traversed highways, mountain passes, and coastal routes in hand-controlled vehicles.\",\n        fullStory: [\n            \"On 15 December 2024, five drivers with physical disabilities set off from Modern School in New Delhi on an unprecedented 6,000 km expedition across India.\",\n            \"Flagged off by Paralympic legend Padma Shri Dr Deepa Malik, the convoy pushed through rain, highway detours, and inaccessible roadside stops, driving all the way to Rameshwaram and Dhanushkodi at the southern border.\",\n            \"Along the way, the team audited highway dhabas, petrol stations, and hotels, demonstrating that persons with disability can lead long-distance expeditions independently.\",\n            \"On 3 January 2025, the convoy returned triumphantly to Delhi, establishing a historic milestone for adaptive driving in India.\"\n        ],\n        quote: \"Good company in a journey makes the way seem shorter.\"\n    },\n    {\n        slug: \"project-udaan-graduates\",\n        title: \"From Code Class to Career: Project Udaan Stories\",\n        subtitle: \"How free laptop repair and web programming courses are changing lives in Gurgaon & Jodhpur.\",\n        category: \"Skills & Jobs\",\n        date: \"2023\",\n        author: \"Project Udaan Team\",\n        image: \"/images/stories/story-04.jpg\",\n        excerpt: \"In 2023, Sangati assessed 170 candidates with disability for certified technical training in laptop repair, DTP, and web design.\",\n        fullStory: [\n            \"Under Project Udaan, Sangati provides tuition-free tech education tailored to individual learning needs. Partnering with Codegeeko and JetKing, students master CompTIA A+ hardware repair, Python, and front-end development.\",\n            \"At our centers in Gurgaon and Jodhpur, trainees gain hands-on access to test hardware, screwdrivers, and soldering stations.\",\n            \"Upon graduation, candidates are listed on the Sangati Job Portal, receiving 1-on-1 resume guidance and interview preparation until they secure dignified employment.\"\n        ],\n        quote: \"Skill is non-disabled. Given the right tools, our candidates out-code and out-repair the competition.\"\n    },\n    {\n        slug: \"delhi-half-marathon-2023\",\n        title: \"25 Sangati Athletes Triumph at Delhi Half-Marathon\",\n        subtitle: \"Running in the Champions with Disability segment with grit and pride.\",\n        category: \"Sports & Wellness\",\n        date: \"Oct 2023\",\n        author: \"Sangati Sports Club\",\n        image: \"/images/stories/story-05.jpg\",\n        excerpt: \"A proud 25-member contingent of wheelchair runners and amputee athletes represented Sangati at the Vedanta Delhi Half-Marathon.\",\n        fullStory: [\n            \"In October 2023, the streets of New Delhi echoed with cheers as 25 Sangati athletes lined up for the Vedanta Delhi Half-Marathon under the Champions with Disability category.\",\n            \"Participants of all ages pushed their wheelchairs and hand-cycles across the finish line, celebrating visibility and sportsmanship.\",\n            \"The event highlighted the urgent need for accessible sports infrastructure, adaptive gym equipment, and inclusive athletic events across Indian cities.\"\n        ],\n        quote: \"We run not for sympathy, but for speed, endurance, and equal space on the tarmac.\"\n    },\n    {\n        slug: \"rural-health-bathri-camp\",\n        title: \"Bringing Critical Healthcare to Himachal’s Hills\",\n        subtitle: \"Serving 300 OPD patients daily at our Bathri center and screening 140 women for cancer.\",\n        category: \"Health Care\",\n        date: \"March 2024\",\n        author: \"Sangati Medical Team\",\n        image: \"/images/stories/story-06.jpg\",\n        excerpt: \"Deep in Dalhousie, Himachal Pradesh, Sangati operates a rural health center providing free OPD, deliveries, and specialized cancer detection.\",\n        fullStory: [\n            \"In remote mountain villages, accessing basic healthcare or diagnostic screening requires arduous travel down steep slopes.\",\n            \"Sangati’s critical care centre in Bathri, Himachal Pradesh serves as a lifeline for neighboring villages, treating over 300 OPD patients daily and supporting medically assisted births.\",\n            \"In March 2024, Sangati organized a major health camp screening 140 people — 80 percent of them women — with mammography, Pap smear, ENT, and physiological checks.\"\n        ],\n        quote: \"Healthcare must reach the mountain peak, not demand that the sick climb down.\"\n    }\n];\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(rsc)/./content/stories.ts\n");

